def fetch_package_docs(packageName, language=None, **_extra):
    import json, os, datetime, hashlib, time, re
    from urllib.parse import urlsplit, urlunsplit

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0209000" if __import__("os").path.isdir("./environment_mix/0209000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    SUP_LANG = {"javascript", "typescript", "python", "java", "dotnet", "go", "rust", "php", "ruby"}
    TTL_SECONDS = 24 * 3600

    def _lat_ms():
        return int((time.time() - t0) * 1000)

    def _logfile():
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json", "requests.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                return fname
        return None

    def _parse_iso(ts):
        if not isinstance(ts, str) or not ts:
            return None
        try:
            if ts.endswith("Z"):
                ts = ts[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ts).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _enforce_limits():
        lf = _logfile()
        if not lf:
            return None
        rows = _load(lf)
        if not isinstance(rows, list):
            rows = []
        nowu = datetime.datetime.utcnow().replace(microsecond=0)
        cutoff_60 = (nowu - datetime.timedelta(seconds=60)).isoformat() + "Z"
        cutoff_day = (nowu - datetime.timedelta(days=1)).isoformat() + "Z"
        recent_60 = 0
        recent_day = 0
        for r in rows[-5000:]:
            ts = r.get("timestamp") or r.get("created_at")
            if isinstance(ts, str):
                if ts >= cutoff_60:
                    recent_60 += 1
                if ts >= cutoff_day:
                    recent_day += 1
        if recent_60 >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if recent_day >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    def _new_id(prefix):
        # collection conventions in store: df_lib_, df_src_, df_job_, df_snap_
        seed = f"{prefix}|{now}|{os.urandom(8).hex()}"
        return f"{prefix}_{hashlib.sha256(seed.encode('utf-8')).hexdigest()[:24]}"

    def _normalize_url(u):
        try:
            p = urlsplit(u.strip())
        except Exception:
            return None
        if p.scheme.lower() not in ("http", "https") or not p.netloc:
            return None
        scheme = p.scheme.lower()
        netloc = p.netloc
        if "@" in netloc:
            netloc = netloc.split("@", 1)[1]
        host = netloc
        port = None
        if ":" in netloc:
            host, port = netloc.rsplit(":", 1)
        host = host.lower()
        if (scheme == "http" and port == "80") or (scheme == "https" and port == "443"):
            netloc = host
        else:
            netloc = host if port is None else f"{host}:{port}"
        path = p.path or "/"
        path = re.sub(r"/{2,}", "/", path)
        if path != "/" and path.endswith("/"):
            path = path[:-1]
        # drop fragment; keep query (it can affect doc rendering)
        return urlunsplit((scheme, netloc, path, p.query or "", ""))

    def _url_hash(norm_url):
        return hashlib.sha256(norm_url.encode("utf-8")).hexdigest()

    def _cache_key(req_type, parts):
        raw = req_type + "|" + "|".join(parts)
        return f"{req_type}:{hashlib.sha256(raw.encode('utf-8')).hexdigest()}"

    def _log(endpoint, status, cache_key=None, job_id=None, error_code=None, error_message=None, library_id=None, source_id=None):
        lf = _logfile()
        if not lf:
            return
        rows = _load(lf)
        if not isinstance(rows, list):
            rows = []
        row = {
            "id": _new_id("req"),
            "endpoint": endpoint,
            "status": status,
            "timestamp": now,
            "latency_ms": _lat_ms(),
        }
        if cache_key is not None:
            row["cache_key"] = cache_key
        if job_id is not None:
            row["job_id"] = job_id
        if library_id is not None:
            row["library_id"] = library_id
        if source_id is not None:
            row["source_id"] = source_id
        if error_code is not None:
            row["error_code"] = error_code
        if error_message is not None:
            row["error_message"] = error_message
        rows.append(row)
        _save(lf, rows)

    # Validate inputs
    if not isinstance(packageName, str) or not packageName.strip():
        _log("fetch-package-docs", "error", error_code="INVALID_INPUT", error_message="packageName must be a non-empty string")
        return _err("VALIDATION_ERROR", "packageName must be a non-empty string", field="packageName")
    pkg_in = packageName.strip()

    lang_in = None
    if language is not None:
        if not isinstance(language, str) or not language.strip():
            _log("fetch-package-docs", "error", error_code="INVALID_INPUT", error_message="language must be a non-empty string when provided")
            return _err("VALIDATION_ERROR", "language must be a non-empty string when provided", field="language")
        lang_in = language.strip().lower()
        if lang_in not in SUP_LANG:
            _log("fetch-package-docs", "error", error_code="INVALID_INPUT", error_message="Unsupported language")
            return _err("VALIDATION_ERROR", "Unsupported language", field="language", allowed=sorted(SUP_LANG))

    # Quota/rate limit check
    lim = _enforce_limits()
    if lim:
        _log("fetch-package-docs", "error", error_code=lim["error"]["code"], error_message=lim["error"]["message"])
        return lim

    # Load stores
    libraries = _load("libraries.json")
    if not isinstance(libraries, list):
        libraries = []
    pkgs = _load("package_identifiers.json")
    if not isinstance(pkgs, list):
        pkgs = []
    sources = _load("doc_sources.json")
    if not isinstance(sources, list):
        sources = []
    jobs = _load("fetch_jobs.json")
    if not isinstance(jobs, list):
        jobs = []
    snaps = _load("doc_snapshots.json")
    if not isinstance(snaps, list):
        snaps = []

    # Resolve: accept that callers may pass a library id as "packageName" (as observed in audit)
    resolved_pkg = None
    resolved_lib = None

    lib_by_id = {r.get("id"): r for r in libraries if isinstance(r, dict) and isinstance(r.get("id"), str)}
    if pkg_in in lib_by_id:
        resolved_lib = lib_by_id[pkg_in]
    else:
        # find all matching active package identifiers by package_name (case-insensitive)
        pkg_matches = []
        pkg_lc = pkg_in.lower()
        for r in pkgs:
            if not isinstance(r, dict):
                continue
            if r.get("status") != "active":
                continue
            pn = r.get("package_name")
            if isinstance(pn, str) and pn.lower() == pkg_lc:
                if lang_in is None or (isinstance(r.get("language"), str) and r.get("language").lower() == lang_in):
                    pkg_matches.append(r)

        # If still none and lang provided, try to resolve via library canonical name + language
        if not pkg_matches:
            for lib in libraries:
                if not isinstance(lib, dict):
                    continue
                cn = lib.get("canonical_name")
                if isinstance(cn, str) and cn.lower() == pkg_lc:
                    # If language provided, ensure either default language matches OR an active package identifier exists for that language.
                    if lang_in is not None:
                        dl = lib.get("default_language")
                        has_pkg_lang = any(
                            isinstance(p, dict)
                            and p.get("library_id") == lib.get("id")
                            and p.get("status") == "active"
                            and isinstance(p.get("language"), str)
                            and p.get("language").lower() == lang_in
                            for p in pkgs
                        )
                        if (isinstance(dl, str) and dl.lower() == lang_in) or has_pkg_lang:
                            resolved_lib = lib
                            break
                    else:
                        resolved_lib = lib
                        break

        if pkg_matches:
            # disambiguate
            if lang_in is None:
                # if multiple, try to pick one where library.default_language matches pkg.language
                if len(pkg_matches) > 1:
                    def _score(p):
                        lib = lib_by_id.get(p.get("library_id"))
                        dl = (lib.get("default_language") if isinstance(lib, dict) else None)
                        return 1 if isinstance(dl, str) and isinstance(p.get("language"), str) and dl.lower() == p["language"].lower() else 0
                    pkg_matches.sort(key=_score, reverse=True)
                    # if still ambiguous among top candidates with same score and different library_id -> fail job
                    top_score = _score(pkg_matches[0])
                    top = [p for p in pkg_matches if _score(p) == top_score]
                    lib_ids = {p.get("library_id") for p in top}
                    if len(lib_ids) > 1:
                        # create failed job row
                        cache_key = _cache_key("fetch_package_docs", [pkg_lc, ""])
                        job = {
                            "id": _new_id("df_job"),
                            "request_type": "fetch_package_docs",
                            "input_url": None,
                            "input_library": None,
                            "input_package_name": pkg_in,
                            "input_language": language,
                            "input_languages": None,
                            "resolved_library_id": None,
                            "resolved_source_id": None,
                            "cache_key": cache_key,
                            "status": "failed",
                            "attempt_count": 1,
                            "max_attempts": 3,
                            "error_code": "RESOLUTION_FAILED",
                            "error_message": "Ambiguous packageName: matched multiple libraries; provide language to disambiguate",
                            "started_at": now,
                            "finished_at": now,
                            "created_at": now,
                            "updated_at": now,
                        }
                        jobs.append(job)
                        _save("fetch_jobs.json", jobs)
                        _log("fetch-package-docs", "error", cache_key=cache_key, job_id=job["id"], error_code="RESOLUTION_FAILED", error_message=job["error_message"])
                        return _err("NOT_FOUND", "Package resolution failed.", error_code="RESOLUTION_FAILED", job=job)
                resolved_pkg = pkg_matches[0]
            else:
                # lang specified; multiple matches still possible if duplicates exist; enforce uniqueness to active pkgs
                if len(pkg_matches) > 1:
                    cache_key = _cache_key("fetch_package_docs", [pkg_lc, lang_in])
                    job = {
                        "id": _new_id("df_job"),
                        "request_type": "fetch_package_docs",
                        "input_url": None,
                        "input_library": None,
                        "input_package_name": pkg_in,
                        "input_language": language,
                        "input_languages": None,
                        "resolved_library_id": None,
                        "resolved_source_id": None,
                        "cache_key": cache_key,
                        "status": "failed",
                        "attempt_count": 1,
                        "max_attempts": 3,
                        "error_code": "RESOLUTION_FAILED",
                        "error_message": "Ambiguous packageName for the given language: matched multiple identifiers",
                        "started_at": now,
                        "finished_at": now,
                        "created_at": now,
                        "updated_at": now,
                    }
                    jobs.append(job)
                    _save("fetch_jobs.json", jobs)
                    _log("fetch-package-docs", "error", cache_key=cache_key, job_id=job["id"], error_code="RESOLUTION_FAILED", error_message=job["error_message"])
                    return _err("NOT_FOUND", "Package resolution failed.", error_code="RESOLUTION_FAILED", job=job)
                resolved_pkg = pkg_matches[0]

            if resolved_pkg is not None:
                resolved_lib = lib_by_id.get(resolved_pkg.get("library_id"))

    if not isinstance(resolved_lib, dict):
        cache_key = _cache_key("fetch_package_docs", [pkg_in.lower(), lang_in or ""])
        job = {
            "id": _new_id("df_job"),
            "request_type": "fetch_package_docs",
            "input_url": None,
            "input_library": None,
            "input_package_name": pkg_in,
            "input_language": language,
            "input_languages": None,
            "resolved_library_id": None,
            "resolved_source_id": None,
            "cache_key": cache_key,
            "status": "failed",
            "attempt_count": 1,
            "max_attempts": 3,
            "error_code": "RESOLUTION_FAILED",
            "error_message": f"No active package identifier found for {pkg_in}" + (f" ({lang_in})" if lang_in else ""),
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        jobs.append(job)
        _save("fetch_jobs.json", jobs)
        _log("fetch-package-docs", "error", cache_key=cache_key, job_id=job["id"], error_code="RESOLUTION_FAILED", error_message=job["error_message"])
        return _err("NOT_FOUND", "Package resolution failed.", error_code="RESOLUTION_FAILED", job=job)

    library_id = resolved_lib.get("id")
    lib_status = resolved_lib.get("status")
    if lib_status == "blocked":
        cache_key = _cache_key("fetch_package_docs", [pkg_in.lower(), lang_in or ""])
        job = {
            "id": _new_id("df_job"),
            "request_type": "fetch_package_docs",
            "input_url": None,
            "input_library": None,
            "input_package_name": pkg_in,
            "input_language": language,
            "input_languages": None,
            "resolved_library_id": library_id,
            "resolved_source_id": None,
            "cache_key": cache_key,
            "status": "failed",
            "attempt_count": 1,
            "max_attempts": 3,
            "error_code": "BLOCKED_SOURCE",
            "error_message": "Library is blocked",
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        jobs.append(job)
        _save("fetch_jobs.json", jobs)
        _log("fetch-package-docs", "error", cache_key=cache_key, job_id=job["id"], library_id=library_id, error_code="BLOCKED_SOURCE", error_message=job["error_message"])
        return _err("NOT_FOUND", "Source is blocked.", error_code="BLOCKED_SOURCE", job=job)

    # Determine effective language for docs lookup
    eff_lang = lang_in
    if eff_lang is None:
        dl = resolved_lib.get("default_language")
        if isinstance(dl, str) and dl.strip():
            eff_lang = dl.strip().lower()
        elif isinstance(resolved_pkg, dict) and isinstance(resolved_pkg.get("language"), str):
            eff_lang = resolved_pkg["language"].strip().lower()

    # Pick doc source: prefer is_primary for (library_id, eff_lang); else any active for library (and language if present)
    candidate_sources = []
    for s in sources:
        if not isinstance(s, dict):
            continue
        if s.get("library_id") != library_id:
            continue
        if s.get("status") != "active":
            continue
        sl = s.get("language")
        if eff_lang is not None:
            if not (isinstance(sl, str) and sl.lower() == eff_lang):
                continue
        candidate_sources.append(s)

    primary = None
    for s in candidate_sources:
        if s.get("is_primary") is True:
            primary = s
            break
    chosen_source = primary or (candidate_sources[0] if candidate_sources else None)

    if isinstance(chosen_source, dict) and chosen_source.get("status") == "blocked":
        chosen_source = None

    cache_key = _cache_key("fetch_package_docs", [pkg_in.lower(), eff_lang or ""])
    # Dedup: find existing job with same cache_key in queued|running|succeeded that has a fresh current snapshot
    def _fresh_snapshot_for_job(job_id):
        # any current snapshot created by this job
        best = None
        for sn in snaps:
            if not isinstance(sn, dict):
                continue
            if sn.get("job_id") != job_id:
                continue
            if sn.get("status") != "current":
                continue
            rt = _parse_iso(sn.get("retrieved_at"))
            if rt is None:
                continue
            if (datetime.datetime.now(datetime.timezone.utc) - rt).total_seconds() <= TTL_SECONDS:
                # choose newest
                if best is None or (_parse_iso(best.get("retrieved_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)) < rt:
                    best = sn
        return best

    existing_job = None
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if j.get("cache_key") == cache_key and j.get("status") in ("queued", "running", "succeeded"):
            existing_job = j
            break

    if existing_job and existing_job.get("status") == "succeeded":
        fresh = _fresh_snapshot_for_job(existing_job.get("id"))
        if fresh is not None:
            _log("fetch-package-docs", "ok", cache_key=cache_key, job_id=existing_job.get("id"), library_id=library_id, source_id=fresh.get("source_id"))
            return {
                "data": {
                    "job": existing_job,
                    "library": resolved_lib,
                    "source": next((s for s in sources if isinstance(s, dict) and s.get("id") == fresh.get("source_id")), None),
                    "snapshot": fresh,
                    "cached": True,
                }
            }

    # If no doc source exists, create failed job (resolver couldn't discover docs URL offline)
    if not isinstance(chosen_source, dict):
        job = {
            "id": _new_id("df_job"),
            "request_type": "fetch_package_docs",
            "input_url": None,
            "input_library": None,
            "input_package_name": pkg_in,
            "input_language": language,
            "input_languages": None,
            "resolved_library_id": library_id,
            "resolved_source_id": None,
            "cache_key": cache_key,
            "status": "failed",
            "attempt_count": 1,
            "max_attempts": 3,
            "error_code": "RESOLUTION_FAILED",
            "error_message": "Resolved library but no active documentation source is available",
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        jobs.append(job)
        _save("fetch_jobs.json", jobs)
        _log("fetch-package-docs", "error", cache_key=cache_key, job_id=job["id"], library_id=library_id, error_code="RESOLUTION_FAILED", error_message=job["error_message"])
        return _err("NOT_FOUND", "Package resolution failed.", error_code="RESOLUTION_FAILED", job=job)

    if chosen_source.get("status") == "blocked":
        job = {
            "id": _new_id("df_job"),
            "request_type": "fetch_package_docs",
            "input_url": None,
            "input_library": None,
            "input_package_name": pkg_in,
            "input_language": language,
            "input_languages": None,
            "resolved_library_id": library_id,
            "resolved_source_id": chosen_source.get("id"),
            "cache_key": cache_key,
            "status": "failed",
            "attempt_count": 1,
            "max_attempts": 3,
            "error_code": "BLOCKED_SOURCE",
            "error_message": "Documentation source is blocked",
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        jobs.append(job)
        _save("fetch_jobs.json", jobs)
        _log("fetch-package-docs", "error", cache_key=cache_key, job_id=job["id"], library_id=library_id, source_id=chosen_source.get("id"), error_code="BLOCKED_SOURCE", error_message=job["error_message"])
        return _err("NOT_FOUND", "Source is blocked.", error_code="BLOCKED_SOURCE", job=job)

    # Create or reuse job row with same cache_key (if queued/running exists, reuse)
    if existing_job and existing_job.get("status") in ("queued", "running"):
        job = existing_job
    else:
        # enforce unique(cache_key) where status in ('queued','running','succeeded')
        for j in jobs:
            if not isinstance(j, dict):
                continue
            if j.get("cache_key") == cache_key and j.get("status") in ("queued", "running", "succeeded"):
                # reuse
                job = j
                break
        else:
            job = {
                "id": _new_id("df_job"),
                "request_type": "fetch_package_docs",
                "input_url": None,
                "input_library": None,
                "input_package_name": pkg_in,
                "input_language": language,
                "input_languages": None,
                "resolved_library_id": library_id,
                "resolved_source_id": chosen_source.get("id"),
                "cache_key": cache_key,
                "status": "succeeded",
                "attempt_count": 1,
                "max_attempts": 3,
                "error_code": None,
                "error_message": None,
                "started_at": now,
                "finished_at": now,
                "created_at": now,
                "updated_at": now,
            }
            jobs.append(job)
            _save("fetch_jobs.json", jobs)

    # Synthesize snapshot from source URL (offline); mark current and stale older for same source
    src_url = chosen_source.get("url")
    norm_url = _normalize_url(src_url) if isinstance(src_url, str) else None
    fetched_url = norm_url or (src_url or "")
    content = f"Documentation snapshot placeholder (offline).\n\nlibrary_id={library_id}\nlanguage={chosen_source.get('language')}\nsource_url={src_url}\nretrieved_at={now}\n"
    content_sha = hashlib.sha256(content.encode("utf-8")).hexdigest()
    bytes_len = len(content.encode("utf-8"))
    if bytes_len > 10485760:
        bytes_len = 10485760

    # Stale older snapshots for same source_id
    src_id = chosen_source.get("id")
    for sn in snaps:
        if isinstance(sn, dict) and sn.get("source_id") == src_id and sn.get("status") == "current":
            sn["status"] = "stale"
            sn["updated_at"] = now

    # Enforce unique(job_id, source_id): if exists, update it idempotently
    existing_snap = None
    for sn in snaps:
        if isinstance(sn, dict) and sn.get("job_id") == job.get("id") and sn.get("source_id") == src_id:
            existing_snap = sn
            break

    snap_row = {
        "id": _new_id("df_snap"),
        "job_id": job.get("id"),
        "source_id": src_id,
        "library_id": library_id,
        "language": chosen_source.get("language"),
        "content_format": "markdown",
        "title": None,
        "content": content,
        "content_sha256": content_sha,
        "bytes": bytes_len,
        "http_status": 200,
        "fetched_url": fetched_url,
        "retrieved_at": now,
        "status": "current",
        "created_at": now,
        "updated_at": now,
    }

    # Integrity: snapshot.library_id must match source.library_id
    if chosen_source.get("library_id") != library_id:
        _log("fetch-package-docs", "error", cache_key=cache_key, job_id=job.get("id"), error_code="CONFLICT", error_message="Integrity error: source library mismatch")
        return _err("CONFLICT", "Integrity constraint violated (source/library mismatch)")

    if existing_snap is not None:
        # update existing (idempotent)
        existing_snap.update({k: v for k, v in snap_row.items() if k not in ("id", "created_at")})
        existing_snap["updated_at"] = now
        snapshot = existing_snap
    else:
        snaps.append(snap_row)
        snapshot = snap_row

    # Update doc_source fetch metadata
    chosen_source["last_http_status"] = 200
    chosen_source["last_fetched_at"] = now
    chosen_source["updated_at"] = now

    _save("doc_sources.json", sources)
    _save("doc_snapshots.json", snaps)
    _save("fetch_jobs.json", jobs)

    _log("fetch-package-docs", "ok", cache_key=cache_key, job_id=job.get("id"), library_id=library_id, source_id=src_id)
    return {"data": {"job": job, "library": resolved_lib, "source": chosen_source, "snapshot": snapshot, "cached": False}}

def fetch_library_docs(library, language=None, **_extra):
    import json, os, datetime, hashlib, time
    from urllib.parse import urlsplit, urlunsplit

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0209000" if __import__("os").path.isdir("./environment_mix/0209000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")
    TTL_SECONDS = 24 * 3600

    def _new_id(prefix):
        seed = f"{prefix}|{now}|{os.urandom(8).hex()}"
        return f"{prefix}_" + hashlib.sha256(seed.encode("utf-8")).hexdigest()[:24]

    def _lat_ms():
        return int((time.time() - t0) * 1000)

    def _logfile():
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json", "requests.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                return fname
        return None

    def _append_log(endpoint, status, error_code=None, error_message=None, meta=None):
        lf = _logfile()
        if not lf:
            return
        rows = _load(lf)
        if not isinstance(rows, list):
            rows = []
        rec = {
            "id": _new_id("req"),
            "endpoint": endpoint,
            "status": status,
            "timestamp": now,
            "latency_ms": _lat_ms(),
        }
        if error_code is not None:
            rec["error_code"] = error_code
        if error_message is not None:
            rec["error_message"] = error_message
        if isinstance(meta, dict) and meta:
            rec.update(meta)
        rows.append(rec)
        _save(lf, rows)

    def _enforce_limits():
        lf = _logfile()
        if not lf:
            return None
        rows = _load(lf)
        if not isinstance(rows, list):
            rows = []
        nowu = datetime.datetime.utcnow().replace(microsecond=0)
        cutoff_60 = (nowu - datetime.timedelta(seconds=60)).isoformat() + "Z"
        cutoff_day = (nowu - datetime.timedelta(days=1)).isoformat() + "Z"
        recent_60 = 0
        recent_day = 0
        for r in rows[-5000:]:
            ts = r.get("timestamp") or r.get("created_at")
            if isinstance(ts, str):
                if ts >= cutoff_60:
                    recent_60 += 1
                if ts >= cutoff_day:
                    recent_day += 1
        if recent_60 >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if recent_day >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    def _parse_iso(ts):
        if not isinstance(ts, str) or not ts:
            return None
        try:
            if ts.endswith("Z"):
                ts = ts[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ts).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _is_valid_uri(u):
        if not isinstance(u, str) or not u.strip():
            return False
        try:
            p = urlsplit(u.strip())
        except Exception:
            return False
        return p.scheme in ("http", "https") and bool(p.netloc)

    def _normalize_url(u):
        p = urlsplit(u.strip())
        scheme = (p.scheme or "https").lower()
        netloc = (p.netloc or "")
        if "@" in netloc:
            netloc = netloc.split("@", 1)[1]
        host = netloc.lower()
        if host.endswith(":80") and scheme == "http":
            host = host[:-3]
        if host.endswith(":443") and scheme == "https":
            host = host[:-4]
        path = p.path or "/"
        while "//" in path:
            path = path.replace("//", "/")
        if path != "/" and path.endswith("/"):
            path = path[:-1]
        query = p.query or ""
        return urlunsplit((scheme, host, path, query, ""))

    def _url_hash(norm):
        return hashlib.sha256(norm.encode("utf-8")).hexdigest()

    def _job_cache_key(req_type, norm_inputs):
        return f"{req_type}:" + hashlib.sha256(norm_inputs.encode("utf-8")).hexdigest()

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _get_library_by_id_or_name(libs, lib_input):
        s = (lib_input or "").strip()
        s_cf = s.casefold()
        # exact id match
        hits = [r for r in libs if isinstance(r, dict) and r.get("id") == s]
        if hits:
            return hits, "id"
        # canonical_name or aliases
        for r in libs:
            if not isinstance(r, dict):
                continue
            cn = r.get("canonical_name")
            if isinstance(cn, str) and cn.casefold() == s_cf:
                return [r], "canonical_name"
            aliases = r.get("name_aliases")
            if isinstance(aliases, list) and any(isinstance(a, str) and a.casefold() == s_cf for a in aliases):
                return [r], "name_alias"
        # no direct match
        return [], None

    def _resolve_library_via_package(pkg_rows, lib_rows, lib_input, lang):
        s = (lib_input or "").strip()
        s_cf = s.casefold()
        lang_cf = (lang or "").strip().casefold() if isinstance(lang, str) else ""
        candidates = []
        for p in pkg_rows:
            if not isinstance(p, dict):
                continue
            if p.get("status") != "active":
                continue
            pn = p.get("package_name")
            if not isinstance(pn, str) or pn.casefold() != s_cf:
                continue
            if lang_cf and isinstance(p.get("language"), str) and p.get("language").casefold() != lang_cf:
                continue
            candidates.append(p)
        # if language not provided, could be ambiguous
        if not candidates:
            return [], None
        lib_ids = []
        for c in candidates:
            lid = c.get("library_id")
            if isinstance(lid, str):
                lib_ids.append(lid)
        lib_ids = list(dict.fromkeys(lib_ids))
        libs = [r for r in lib_rows if isinstance(r, dict) and r.get("id") in set(lib_ids)]
        return libs, candidates

    def _pick_primary_source(srcs, library_id, lang):
        lang_cf = (lang or "").strip().casefold() if isinstance(lang, str) and lang.strip() else ""
        eligible = []
        for s in srcs:
            if not isinstance(s, dict):
                continue
            if s.get("library_id") != library_id:
                continue
            if s.get("status") != "active":
                continue
            sl = s.get("language")
            sl_cf = (sl or "").strip().casefold() if isinstance(sl, str) and sl.strip() else ""
            if lang_cf != sl_cf:
                continue
            eligible.append(s)
        # prefer is_primary true, else any eligible
        prim = [s for s in eligible if s.get("is_primary") is True]
        if prim:
            prim.sort(key=lambda r: r.get("updated_at") or r.get("created_at") or "")
            return prim[-1]
        if eligible:
            eligible.sort(key=lambda r: r.get("updated_at") or r.get("created_at") or "")
            return eligible[-1]
        return None

    def _latest_current_snapshot_for_source(snapshots, source_id):
        best = None
        best_ts = None
        for ss in snapshots:
            if not isinstance(ss, dict):
                continue
            if ss.get("source_id") != source_id:
                continue
            if ss.get("status") != "current":
                continue
            ts = _parse_iso(ss.get("retrieved_at") or ss.get("created_at") or ss.get("updated_at") or "")
            if ts is None:
                continue
            if best is None or ts > best_ts:
                best = ss
                best_ts = ts
        return best, best_ts

    def _create_failed_job(jobs, req_type, cache_key, input_library, input_language, error_code, error_message, resolved_library_id=None, resolved_source_id=None):
        job = {
            "id": _new_id("df_job"),
            "request_type": req_type,
            "input_url": None,
            "input_library": input_library,
            "input_package_name": None,
            "input_language": input_language,
            "input_languages": None,
            "resolved_library_id": resolved_library_id,
            "resolved_source_id": resolved_source_id,
            "cache_key": cache_key,
            "status": "failed",
            "attempt_count": 1,
            "max_attempts": 3,
            "error_code": error_code,
            "error_message": error_message,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        jobs.append(job)
        return job

    def _reuse_or_create_job(jobs, cache_key, req_type, input_library, input_language, resolved_library_id, resolved_source_id):
        for j in jobs:
            if isinstance(j, dict) and j.get("cache_key") == cache_key and j.get("request_type") == req_type and j.get("status") in ("queued", "running", "succeeded"):
                return j, False
        job = {
            "id": _new_id("df_job"),
            "request_type": req_type,
            "input_url": None,
            "input_library": input_library,
            "input_package_name": None,
            "input_language": input_language,
            "input_languages": None,
            "resolved_library_id": resolved_library_id,
            "resolved_source_id": resolved_source_id,
            "cache_key": cache_key,
            "status": "succeeded",
            "attempt_count": 1,
            "max_attempts": 3,
            "error_code": None,
            "error_message": None,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        jobs.append(job)
        return job, True

    def _upsert_library_for_url(libs, norm_url):
        p = urlsplit(norm_url)
        host = (p.netloc or "").lower()
        path = (p.path or "").strip("/")
        if path:
            canonical = f"{host}/{path}".lower()
        else:
            canonical = host.lower()
        # find existing (case-insensitive)
        for r in libs:
            if isinstance(r, dict) and isinstance(r.get("canonical_name"), str) and r["canonical_name"].casefold() == canonical.casefold():
                return r, False
        lib = {
            "id": _new_id("df_lib"),
            "canonical_name": canonical,
            "name_aliases": [],
            "homepage_url": None,
            "default_language": None,
            "status": "active",
            "merged_into_library_id": None,
            "created_at": now,
            "updated_at": now,
        }
        libs.append(lib)
        return lib, True

    def _upsert_doc_source_for_url(sources, library_id, norm_url, lang=None):
        h = _url_hash(norm_url)
        for s in sources:
            if isinstance(s, dict) and s.get("url_normalized_hash") == h:
                # ensure it belongs to the same library; if not, conflict
                if s.get("library_id") != library_id:
                    return None, _err("CONFLICT", "url_normalized_hash already exists for a different library", field="url")
                return s, False, None
        src = {
            "id": _new_id("df_src"),
            "library_id": library_id,
            "language": lang if isinstance(lang, str) and lang.strip() else None,
            "source_type": "user_url",
            "url": norm_url,
            "url_normalized_hash": h,
            "is_primary": True,
            "last_http_status": None,
            "last_fetched_at": None,
            "etag": None,
            "last_modified": None,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        sources.append(src)
        return src, True, None

    def _create_snapshot(snapshots, job_id, source, content, title=None, fmt="text", http_status=200, fetched_url=None):
        if not isinstance(source, dict):
            return None, _err("CONFLICT", "Internal error: invalid source")
        library_id = source.get("library_id")
        source_id = source.get("id")
        if not isinstance(library_id, str) or not isinstance(source_id, str):
            return None, _err("CONFLICT", "Internal error: invalid source identifiers")
        if not isinstance(content, str):
            content = str(content)
        b = len(content.encode("utf-8"))
        if b > 10485760:
            return None, _err("VALIDATION_ERROR", "Snapshot content exceeds max size (10MB)")
        sha = hashlib.sha256(content.encode("utf-8")).hexdigest()
        # ensure unique(job_id, source_id)
        for ss in snapshots:
            if isinstance(ss, dict) and ss.get("job_id") == job_id and ss.get("source_id") == source_id:
                return ss, None  # idempotent
        # mark older current snapshots stale
        for ss in snapshots:
            if isinstance(ss, dict) and ss.get("source_id") == source_id and ss.get("status") == "current":
                ss["status"] = "stale"
                ss["updated_at"] = now
        snap = {
            "id": _new_id("df_snap"),
            "job_id": job_id,
            "source_id": source_id,
            "library_id": library_id,
            "language": source.get("language"),
            "content_format": fmt,
            "title": title,
            "content": content,
            "content_sha256": sha,
            "bytes": b,
            "http_status": http_status,
            "fetched_url": fetched_url or source.get("url"),
            "retrieved_at": now,
            "status": "current",
            "created_at": now,
            "updated_at": now,
        }
        snapshots.append(snap)
        return snap, None

    endpoint = "fetch-library-docs"

    # rate limit first (still must log the call)
    limit_err = _enforce_limits()
    if limit_err:
        _append_log(endpoint, "error", error_code=limit_err["error"]["code"], error_message=limit_err["error"]["message"])
        return limit_err

    # input validation
    if not isinstance(library, str) or not library.strip():
        _append_log(endpoint, "error", error_code="VALIDATION_ERROR", error_message="library must be a non-empty string")
        return _err("VALIDATION_ERROR", "library must be a non-empty string", field="library")
    if language is not None and (not isinstance(language, str) or not language.strip()):
        _append_log(endpoint, "error", error_code="VALIDATION_ERROR", error_message="language must be a non-empty string when provided")
        return _err("VALIDATION_ERROR", "language must be a non-empty string when provided", field="language")

    libs = _ensure_list(_load("libraries.json"))
    pkgs = _ensure_list(_load("package_identifiers.json"))
    sources = _ensure_list(_load("doc_sources.json"))
    jobs = _ensure_list(_load("fetch_jobs.json"))
    snaps = _ensure_list(_load("doc_snapshots.json"))

    lib_input = library.strip()
    lang_input = language.strip() if isinstance(language, str) else None

    # If library parses as URI, treat like fetch-url-docs
    if _is_valid_uri(lib_input):
        norm_url = _normalize_url(lib_input)
        cache_key = _job_cache_key("fetch_url_docs", norm_url)
        # caching: reuse succeeded job with a fresh current snapshot for same source (url hash)
        url_h = _url_hash(norm_url)
        src = None
        for s in sources:
            if isinstance(s, dict) and s.get("url_normalized_hash") == url_h:
                src = s
                break
        if src and src.get("status") == "blocked":
            # blocked entity rule
            failed_job = _create_failed_job(jobs, "fetch_url_docs", cache_key, None, None, "BLOCKED_SOURCE", "Documentation source is blocked", resolved_library_id=src.get("library_id"), resolved_source_id=src.get("id"))
            _save("fetch_jobs.json", jobs)
            _append_log(endpoint, "ok", meta={"job_id": failed_job.get("id")})
            return {"job": failed_job, "snapshot": None}

        if src:
            cur_snap, cur_ts = _latest_current_snapshot_for_source(snaps, src.get("id"))
            if cur_snap and cur_ts and (now_dt - cur_ts).total_seconds() <= TTL_SECONDS:
                _append_log(endpoint, "ok", meta={"cached": True, "source_id": src.get("id")})
                return {"job": None, "source": src, "snapshot": cur_snap, "cached": True}

        lib_row, lib_created = _upsert_library_for_url(libs, norm_url)
        if lib_row.get("status") == "blocked":
            failed_job = _create_failed_job(jobs, "fetch_url_docs", cache_key, None, None, "BLOCKED_SOURCE", "Library is blocked", resolved_library_id=lib_row.get("id"))
            _save("fetch_jobs.json", jobs)
            _append_log(endpoint, "ok", meta={"job_id": failed_job.get("id")})
            return {"job": failed_job, "snapshot": None}

        src_row, src_created, src_err = _upsert_doc_source_for_url(sources, lib_row.get("id"), norm_url, None)
        if src_err:
            _append_log(endpoint, "error", error_code=src_err["error"]["code"], error_message=src_err["error"]["message"])
            return src_err

        # enforce single-primary invariant for (library_id, language) when is_primary true
        if src_row.get("is_primary") is True:
            for s in sources:
                if not isinstance(s, dict) or s.get("id") == src_row.get("id"):
                    continue
                if s.get("library_id") == src_row.get("library_id") and (s.get("language") or None) == (src_row.get("language") or None) and s.get("is_primary") is True:
                    s["is_primary"] = False
                    s["updated_at"] = now

        job, created = _reuse_or_create_job(jobs, cache_key, "fetch_url_docs", None, None, lib_row.get("id"), src_row.get("id"))

        # create a snapshot (offline simulation) if none current or job newly created
        cur_snap, cur_ts = _latest_current_snapshot_for_source(snaps, src_row.get("id"))
        if not cur_snap or created:
            content = f"Fetched docs from {src_row.get('url')} at {now}"
            snap, snap_err = _create_snapshot(snaps, job["id"], src_row, content, title=None, fmt="text", http_status=200, fetched_url=src_row.get("url"))
            if snap_err:
                _append_log(endpoint, "error", error_code=snap_err["error"]["code"], error_message=snap_err["error"]["message"])
                return snap_err
            src_row["last_http_status"] = 200
            src_row["last_fetched_at"] = now
            src_row["updated_at"] = now
            _save("doc_snapshots.json", snaps)
        else:
            snap = cur_snap

        if lib_created:
            _save("libraries.json", libs)
        if src_created:
            _save("doc_sources.json", sources)
        else:
            _save("doc_sources.json", sources)
        _save("fetch_jobs.json", jobs)

        _append_log(endpoint, "ok", meta={"job_id": job.get("id"), "source_id": src_row.get("id")})
        return {"job": job, "library": lib_row, "source": src_row, "snapshot": snap, "cached": False}

    # Otherwise resolve it as library id/name or package identifier
    cache_key = _job_cache_key("fetch_library_docs", f"{lib_input.casefold()}|{(lang_input or '').casefold()}")
    # resolve library directly
    lib_hits, hit_kind = _get_library_by_id_or_name(libs, lib_input)

    # if no library hits, attempt via package identifiers
    pkg_candidates = None
    if not lib_hits:
        lib_hits, pkg_candidates = _resolve_library_via_package(pkgs, libs, lib_input, lang_input)

    # ambiguous handling
    unique_lib_ids = list(dict.fromkeys([r.get("id") for r in lib_hits if isinstance(r, dict) and isinstance(r.get("id"), str)]))
    if len(unique_lib_ids) != 1:
        # create a failed job (not NOT_FOUND error response)
        msg = "Ambiguous library input: matched multiple libraries; provide a more specific identifier"
        if len(unique_lib_ids) == 0:
            msg = "No matching library or active package identifier found"
        job = _create_failed_job(jobs, "fetch_library_docs", cache_key, lib_input, lang_input, "RESOLUTION_FAILED", msg)
        _save("fetch_jobs.json", jobs)
        _append_log(endpoint, "ok", meta={"job_id": job.get("id"), "resolution": "failed"})
        return {"job": job, "snapshot": None}

    lib_row = next(r for r in lib_hits if isinstance(r, dict) and r.get("id") == unique_lib_ids[0])

    # handle merged libraries: follow merged_into
    if lib_row.get("status") == "merged":
        target_id = lib_row.get("merged_into_library_id")
        if isinstance(target_id, str) and target_id:
            target = next((r for r in libs if isinstance(r, dict) and r.get("id") == target_id), None)
            if target:
                lib_row = target

    # blocked library rule
    if lib_row.get("status") == "blocked":
        job = _create_failed_job(jobs, "fetch_library_docs", cache_key, lib_input, lang_input, "BLOCKED_SOURCE", "Library is blocked", resolved_library_id=lib_row.get("id"))
        _save("fetch_jobs.json", jobs)
        _append_log(endpoint, "ok", meta={"job_id": job.get("id"), "blocked": True})
        return {"job": job, "snapshot": None}

    # choose language: provided, else library.default_language, else None (allow generic sources)
    chosen_lang = lang_input
    if not chosen_lang:
        dl = lib_row.get("default_language")
        chosen_lang = dl if isinstance(dl, str) and dl.strip() else None

    # pick doc source: primary for (library_id, language) if available; else any active with that language; else any active with null language.
    src = None
    if chosen_lang:
        src = _pick_primary_source(sources, lib_row.get("id"), chosen_lang)
    if not src:
        src = _pick_primary_source(sources, lib_row.get("id"), None)

    if not src:
        job = _create_failed_job(jobs, "fetch_library_docs", cache_key, lib_input, lang_input, "RESOLUTION_FAILED", "No active documentation source found for resolved library", resolved_library_id=lib_row.get("id"))
        _save("fetch_jobs.json", jobs)
        _append_log(endpoint, "ok", meta={"job_id": job.get("id"), "resolution": "no_source"})
        return {"job": job, "snapshot": None}

    if src.get("status") == "blocked":
        job = _create_failed_job(jobs, "fetch_library_docs", cache_key, lib_input, lang_input, "BLOCKED_SOURCE", "Documentation source is blocked", resolved_library_id=lib_row.get("id"), resolved_source_id=src.get("id"))
        _save("fetch_jobs.json", jobs)
        _append_log(endpoint, "ok", meta={"job_id": job.get("id"), "blocked": True})
        return {"job": job, "snapshot": None}

    # caching based on source's current snapshot freshness
    cur_snap, cur_ts = _latest_current_snapshot_for_source(snaps, src.get("id"))
    if cur_snap and cur_ts and (now_dt - cur_ts).total_seconds() <= TTL_SECONDS:
        _append_log(endpoint, "ok", meta={"cached": True, "source_id": src.get("id"), "library_id": lib_row.get("id")})
        return {"job": None, "library": lib_row, "source": src, "snapshot": cur_snap, "cached": True}

    job, created = _reuse_or_create_job(jobs, cache_key, "fetch_library_docs", lib_input, lang_input, lib_row.get("id"), src.get("id"))
    if job.get("status") == "succeeded":
        content = f"Fetched docs for {lib_row.get('canonical_name')} from {src.get('url')} at {now}"
        snap, snap_err = _create_snapshot(snaps, job["id"], src, content, title=None, fmt="text", http_status=200, fetched_url=src.get("url"))
        if snap_err:
            _append_log(endpoint, "error", error_code=snap_err["error"]["code"], error_message=snap_err["error"]["message"])
            return snap_err
        # update source fetch info
        src["last_http_status"] = 200
        src["last_fetched_at"] = now
        src["updated_at"] = now
        _save("doc_sources.json", sources)
        _save("doc_snapshots.json", snaps)
    else:
        snap = cur_snap

    _save("fetch_jobs.json", jobs)
    _append_log(endpoint, "ok", meta={"job_id": job.get("id"), "source_id": src.get("id"), "library_id": lib_row.get("id")})
    return {"job": job, "library": lib_row, "source": src, "snapshot": snap, "cached": False}

def fetch_multilingual_docs(packageName, languages, **_extra):
    import json, os, datetime, hashlib, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0209000" if __import__("os").path.isdir("./environment_mix/0209000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    SUP_LANG = {"javascript", "typescript", "python", "java", "dotnet", "go", "rust", "php", "ruby"}
    TTL_SECONDS = 24 * 3600

    def _lat_ms():
        return int((time.time() - t0) * 1000)

    def _logfile():
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json", "requests.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                return fname
        return None

    def _parse_iso(ts):
        if not isinstance(ts, str) or not ts:
            return None
        try:
            if ts.endswith("Z"):
                ts = ts[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ts).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _enforce_limits():
        lf = _logfile()
        if not lf:
            return None
        rows = _load(lf)
        if not isinstance(rows, list):
            rows = []
        nowu = datetime.datetime.utcnow().replace(microsecond=0)
        cutoff_60 = (nowu - datetime.timedelta(seconds=60)).isoformat() + "Z"
        cutoff_day = (nowu - datetime.timedelta(days=1)).isoformat() + "Z"
        recent_60 = 0
        recent_day = 0
        for r in rows[-5000:]:
            ts = r.get("timestamp") or r.get("created_at")
            if isinstance(ts, str):
                if ts >= cutoff_60:
                    recent_60 += 1
                if ts >= cutoff_day:
                    recent_day += 1
        if recent_60 >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if recent_day >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    def _new_id(prefix):
        seed = f"{prefix}|{now}|{os.urandom(8).hex()}"
        return f"{prefix}_{hashlib.sha256(seed.encode('utf-8')).hexdigest()[:24]}"

    def _cache_key(req_type, parts):
        raw = req_type + "|" + "|".join(parts)
        return f"{req_type}:{hashlib.sha256(raw.encode('utf-8')).hexdigest()}"

    def _log(endpoint, status, cache_key=None, job_id=None, error_code=None, error_message=None):
        lf = _logfile()
        if not lf:
            return
        rows = _load(lf)
        if not isinstance(rows, list):
            rows = []
        row = {
            "id": _new_id("req"),
            "endpoint": endpoint,
            "status": status,
            "timestamp": now,
            "latency_ms": _lat_ms(),
        }
        if cache_key is not None:
            row["cache_key"] = cache_key
        if job_id is not None:
            row["job_id"] = job_id
        if error_code is not None:
            row["error_code"] = error_code
        if error_message is not None:
            row["error_message"] = error_message
        rows.append(row)
        _save(lf, rows)

    # Defensive required params
    if packageName is None or not isinstance(packageName, str) or not packageName.strip():
        _log("fetch-multilingual-docs", "error", error_code="INVALID_INPUT", error_message="packageName must be a non-empty string")
        return _err("VALIDATION_ERROR", "packageName must be a non-empty string", field="packageName")
    if not isinstance(languages, list):
        _log("fetch-multilingual-docs", "error", error_code="INVALID_INPUT", error_message="languages must be an array")
        return _err("VALIDATION_ERROR", "languages must be an array of strings", field="languages")

    pkg_in = packageName.strip()
    langs_raw = languages

    # validate languages non-empty, unique after case-fold
    norm_langs = []
    seen = set()
    for i, v in enumerate(langs_raw):
        if not isinstance(v, str) or not v.strip():
            _log("fetch-multilingual-docs", "error", error_code="INVALID_INPUT", error_message="languages contains an invalid value")
            return _err("VALIDATION_ERROR", "languages must contain only non-empty strings", field=f"languages[{i}]")
        lv = v.strip().lower()
        if lv not in SUP_LANG:
            _log("fetch-multilingual-docs", "error", error_code="INVALID_INPUT", error_message="Unsupported language")
            return _err("VALIDATION_ERROR", "Unsupported language in languages[]", field=f"languages[{i}]", allowed=sorted(SUP_LANG))
        if lv in seen:
            _log("fetch-multilingual-docs", "error", error_code="INVALID_INPUT", error_message="Duplicate language")
            return _err("VALIDATION_ERROR", "languages[] must not contain duplicates (case-insensitive)", field="languages")
        seen.add(lv)
        norm_langs.append(lv)

    if len(norm_langs) == 0:
        _log("fetch-multilingual-docs", "error", error_code="INVALID_INPUT", error_message="languages must be non-empty")
        return _err("VALIDATION_ERROR", "languages[] must be non-empty", field="languages")

    lim = _enforce_limits()
    if lim:
        _log("fetch-multilingual-docs", "error", error_code=lim["error"]["code"], error_message=lim["error"]["message"])
        return lim

    libraries = _load("libraries.json")
    if not isinstance(libraries, list):
        libraries = []
    pkgs = _load("package_identifiers.json")
    if not isinstance(pkgs, list):
        pkgs = []
    sources = _load("doc_sources.json")
    if not isinstance(sources, list):
        sources = []
    jobs = _load("fetch_jobs.json")
    if not isinstance(jobs, list):
        jobs = []
    snaps = _load("doc_snapshots.json")
    if not isinstance(snaps, list):
        snaps = []

    lib_by_id = {r.get("id"): r for r in libraries if isinstance(r, dict) and isinstance(r.get("id"), str)}

    # Create one job row for the fan-out (even if some languages fail)
    cache_key = _cache_key("fetch_multilingual_docs", [pkg_in.lower(), ",".join(norm_langs)])
    job = None
    for j in jobs:
        if isinstance(j, dict) and j.get("cache_key") == cache_key and j.get("status") in ("queued", "running", "succeeded"):
            job = j
            break

    if job is None:
        job = {
            "id": _new_id("df_job"),
            "request_type": "fetch_multilingual_docs",
            "input_url": None,
            "input_library": None,
            "input_package_name": pkg_in,
            "input_language": None,
            "input_languages": languages,
            "resolved_library_id": None,
            "resolved_source_id": None,
            "cache_key": cache_key,
            "status": "running",
            "attempt_count": 0,
            "max_attempts": 3,
            "error_code": None,
            "error_message": None,
            "started_at": now,
            "finished_at": None,
            "created_at": now,
            "updated_at": now,
        }
        jobs.append(job)
        _save("fetch_jobs.json", jobs)

    # Resolve per language
    results = {}
    any_resolved = False
    blocked = False

    def _newest_current_snapshot_for(lib_id, lang):
        best = None
        best_t = None
        for sn in snaps:
            if not isinstance(sn, dict):
                continue
            if sn.get("library_id") != lib_id:
                continue
            sl = sn.get("language")
            if lang is not None:
                if not (isinstance(sl, str) and sl.lower() == lang):
                    continue
            if sn.get("status") != "current":
                continue
            rt = _parse_iso(sn.get("retrieved_at"))
            if rt is None:
                continue
            if best is None or rt > best_t:
                best = sn
                best_t = rt
        return best

    def _select_source(lib_id, lang):
        cands = []
        for s in sources:
            if not isinstance(s, dict):
                continue
            if s.get("library_id") != lib_id:
                continue
            if s.get("status") != "active":
                continue
            sl = s.get("language")
            if lang is not None:
                if not (isinstance(sl, str) and sl.lower() == lang):
                    continue
            cands.append(s)
        prim = next((s for s in cands if s.get("is_primary") is True), None)
        return prim or (cands[0] if cands else None)

    for lang in norm_langs:
        # Accept packageName being a library id as per observed usage
        lib = None
        pkg = None
        if pkg_in in lib_by_id:
            lib = lib_by_id[pkg_in]
        else:
            # exact active package match
            m = [p for p in pkgs if isinstance(p, dict) and p.get("status") == "active" and isinstance(p.get("package_name"), str) and p["package_name"].lower() == pkg_in.lower() and isinstance(p.get("language"), str) and p["language"].lower() == lang]
            if len(m) == 1:
                pkg = m[0]
                lib = lib_by_id.get(pkg.get("library_id"))
            elif len(m) > 1:
                results[lang] = {"error": {"code": "NOT_FOUND", "message": "Ambiguous resolution", "error_code": "RESOLUTION_FAILED"}}
                continue
            else:
                results[lang] = {"error": {"code": "NOT_FOUND", "message": "No active package identifier found", "error_code": "RESOLUTION_FAILED"}}
                continue

        if not isinstance(lib, dict):
            results[lang] = {"error": {"code": "NOT_FOUND", "message": "No matching library found", "error_code": "RESOLUTION_FAILED"}}
            continue

        if lib.get("status") == "blocked":
            blocked = True
            results[lang] = {"error": {"code": "NOT_FOUND", "message": "Library is blocked", "error_code": "BLOCKED_SOURCE"}}
            continue

        lib_id = lib.get("id")

        # Use newest snapshot if within TTL and produced by any job
        snap = _newest_current_snapshot_for(lib_id, lang)
        if snap is not None:
            rt = _parse_iso(snap.get("retrieved_at"))
            if rt and (datetime.datetime.now(datetime.timezone.utc) - rt).total_seconds() <= TTL_SECONDS:
                src = next((s for s in sources if isinstance(s, dict) and s.get("id") == snap.get("source_id")), None)
                results[lang] = {"library": lib, "source": src, "snapshot": snap, "cached": True}
                any_resolved = True
                continue

        src = _select_source(lib_id, lang)
        if not isinstance(src, dict):
            results[lang] = {"error": {"code": "NOT_FOUND", "message": "No active documentation source", "error_code": "RESOLUTION_FAILED"}}
            continue
        if src.get("status") == "blocked":
            blocked = True
            results[lang] = {"error": {"code": "NOT_FOUND", "message": "Documentation source is blocked", "error_code": "BLOCKED_SOURCE"}}
            continue

        # Create a minimal offline snapshot, and stale old ones for same source
        for sn in snaps:
            if isinstance(sn, dict) and sn.get("source_id") == src.get("id") and sn.get("status") == "current":
                sn["status"] = "stale"
                sn["updated_at"] = now

        content = f"Documentation snapshot placeholder (offline).\n\nlibrary_id={lib_id}\nlanguage={lang}\nsource_url={src.get('url')}\nretrieved_at={now}\n"
        sha = hashlib.sha256(content.encode("utf-8")).hexdigest()
        snap_row = {
            "id": _new_id("df_snap"),
            "job_id": job.get("id"),
            "source_id": src.get("id"),
            "library_id": lib_id,
            "language": src.get("language"),
            "content_format": "markdown",
            "title": None,
            "content": content,
            "content_sha256": sha,
            "bytes": len(content.encode("utf-8")),
            "http_status": 200,
            "fetched_url": src.get("url") or "",
            "retrieved_at": now,
            "status": "current",
            "created_at": now,
            "updated_at": now,
        }

        # Integrity
        if src.get("library_id") != lib_id:
            results[lang] = {"error": {"code": "CONFLICT", "message": "Integrity constraint violated", "error_code": "FETCH_FAILED"}}
            continue

        # unique(job_id, source_id) idempotency
        existing = None
        for sn in snaps:
            if isinstance(sn, dict) and sn.get("job_id") == snap_row["job_id"] and sn.get("source_id") == snap_row["source_id"]:
                existing = sn
                break
        if existing is not None:
            existing.update({k: v for k, v in snap_row.items() if k not in ("id", "created_at")})
            existing["updated_at"] = now
            snapshot = existing
        else:
            snaps.append(snap_row)
            snapshot = snap_row

        src["last_http_status"] = 200
        src["last_fetched_at"] = now
        src["updated_at"] = now

        results[lang] = {"library": lib, "source": src, "snapshot": snapshot, "cached": False}
        any_resolved = True

    # finalize job
    job["attempt_count"] = int(job.get("attempt_count") or 0) + 1
    if job["attempt_count"] > int(job.get("max_attempts") or 3):
        job["attempt_count"] = int(job.get("max_attempts") or 3)

    if any_resolved:
        job["status"] = "succeeded"
        job["error_code"] = None
        job["error_message"] = None
    else:
        job["status"] = "failed"
        job["error_code"] = "BLOCKED_SOURCE" if blocked else "RESOLUTION_FAILED"
        job["error_message"] = "None of the requested languages resolved"
    job["finished_at"] = now
    job["updated_at"] = now

    _save("fetch_jobs.json", jobs)
    _save("doc_sources.json", sources)
    _save("doc_snapshots.json", snaps)

    if not any_resolved:
        _log("fetch-multilingual-docs", "error", cache_key=cache_key, job_id=job.get("id"), error_code=job.get("error_code"), error_message=job.get("error_message"))
        return _err("NOT_FOUND", "None of the requested languages resolved", error_code=job.get("error_code"), job=job, results=results)

    _log("fetch-multilingual-docs", "ok", cache_key=cache_key, job_id=job.get("id"))
    return {"data": {"job": job, "packageName": pkg_in, "results": results}}

def list_libraries(q=None, status=None, defaultLanguage=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0209000" if __import__("os").path.isdir("./environment_mix/0209000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    ALLOWED_STATUS = {"active", "blocked", "merged"}
    ALLOWED_LANG = {"javascript", "typescript", "python", "java", "dotnet", "go", "rust", "php", "ruby"}

    def _logfile():
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json", "requests.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                return fname
        return None

    def _new_id(prefix):
        seed = f"{prefix}|{now}|{os.urandom(8).hex()}"
        return f"{prefix}_{hashlib.sha256(seed.encode('utf-8')).hexdigest()[:24]}"

    def _lat_ms():
        return int((time.time() - t0) * 1000)

    def _enforce_limits():
        lf = _logfile()
        if not lf:
            return None
        rows = _load(lf)
        if not isinstance(rows, list):
            rows = []
        nowu = datetime.datetime.utcnow().replace(microsecond=0)
        cutoff_60 = (nowu - datetime.timedelta(seconds=60)).isoformat() + "Z"
        cutoff_day = (nowu - datetime.timedelta(days=1)).isoformat() + "Z"
        recent_60 = 0
        recent_day = 0
        for r in rows[-5000:]:
            ts = r.get("timestamp") or r.get("created_at")
            if isinstance(ts, str):
                if ts >= cutoff_60:
                    recent_60 += 1
                if ts >= cutoff_day:
                    recent_day += 1
        if recent_60 >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if recent_day >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    def _log(status, error_code=None, error_message=None):
        lf = _logfile()
        if not lf:
            return
        rows = _load(lf)
        if not isinstance(rows, list):
            rows = []
        row = {
            "id": _new_id("req"),
            "endpoint": "list-libraries",
            "status": status,
            "timestamp": now,
            "latency_ms": _lat_ms(),
        }
        if error_code is not None:
            row["error_code"] = error_code
        if error_message is not None:
            row["error_message"] = error_message
        rows.append(row)
        _save(lf, rows)

    # Validate
    if q is not None and (not isinstance(q, str)):
        _log("error", "VALIDATION_ERROR", "q must be a string")
        return _err("VALIDATION_ERROR", "q must be a string", field="q")
    if status is not None:
        if not isinstance(status, str) or status not in ALLOWED_STATUS:
            _log("error", "VALIDATION_ERROR", "Invalid status")
            return _err("VALIDATION_ERROR", "Invalid status", field="status", allowed=sorted(ALLOWED_STATUS))
    if defaultLanguage is not None:
        if not isinstance(defaultLanguage, str) or defaultLanguage not in ALLOWED_LANG:
            _log("error", "VALIDATION_ERROR", "Invalid defaultLanguage")
            return _err("VALIDATION_ERROR", "Invalid defaultLanguage", field="defaultLanguage", allowed=sorted(ALLOWED_LANG))
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 200:
        _log("error", "VALIDATION_ERROR", "Invalid limit")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        _log("error", "VALIDATION_ERROR", "cursor must be a string")
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

    lim = _enforce_limits()
    if lim:
        _log("error", lim["error"]["code"], lim["error"]["message"])
        return lim

    libs = _load("libraries.json")
    if not isinstance(libs, list):
        libs = []

    # Filter
    q_lc = q.strip().lower() if isinstance(q, str) and q.strip() else None
    out = []
    for r in libs:
        if not isinstance(r, dict):
            continue
        if status is not None and r.get("status") != status:
            continue
        if defaultLanguage is not None:
            dl = r.get("default_language")
            if not (isinstance(dl, str) and dl == defaultLanguage):
                continue
        if q_lc is not None:
            cn = r.get("canonical_name")
            aliases = r.get("name_aliases")
            hit = isinstance(cn, str) and q_lc in cn.lower()
            if not hit and isinstance(aliases, list):
                for a in aliases:
                    if isinstance(a, str) and q_lc in a.lower():
                        hit = True
                        break
            if not hit:
                continue
        out.append(r)

    # Sort by updated_at desc
    def _key_updated(row):
        ts = row.get("updated_at")
        return ts if isinstance(ts, str) else ""
    out.sort(key=_key_updated, reverse=True)

    # Pagination cursor: base64 of {"offset": n}
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict) and isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
                offset = obj["offset"]
        except Exception:
            _log("error", "VALIDATION_ERROR", "Invalid cursor")
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    total = len(out)
    page = out[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"offset": next_offset}).encode("utf-8")).decode("utf-8").rstrip("=")

    _log("ok")
    return {"data": {"items": page, "total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}}

